import re
data=open('/tmp/o24.txt','rb').read().decode('utf8')
lines=data.split('\r\n')
for i,l in enumerate(lines[1:12],start=1):
    parts=re.findall(r'\x1b\[38;2;([0-9]+);([0-9]+);([0-9]+);48;2;([0-9]+);([0-9]+);([0-9]+)\m(.)'.replace('\\m','m'), l)
    parts=re.findall(r'\x1b\[38;2;([0-9]+);([0-9]+);([0-9]+);48;2;([0-9]+);([0-9]+);([0-9]+)m(.)', l)
    print(i, 'nblocks=',len(parts))
    s=[]
    for f,g,b,fr,fg,fb,ch in parts:
        if (f,g,b)==(fr,fg,fb) and ch==' ': s.append('C')
        elif ch=='\u2580': s.append('.')
        else: s.append('X')
    print('   ', ''.join(s))
    m=re.search(r'\x1b\[0m(.*)$', l)
    tail = m.group(1) if m else None
    # remove rest escapes
    if tail: tail=re.sub(r'\x1b\[38;2;[0-9;]+;48;2;[0-9;]+m(.)\x1b\[0m', lambda mm: '('+mm.group(1)+')', tail)
    print('    text=',repr(tail))
EOF"}

