{"command": "cd /workspace && python3 - <<'EOF'
import re
data=open('/tmp/o24.txt','rb').read().decode('utf8')
lines=data.split('\r\n')
def blocks(l):
    res=[]
    for m in re.finditer(r'\x1b\[38;2;([0-9]+);([0-9]+);([0-9]+);48;2;([0-9]+);([0-9]+);([0-9]+)m(.)\x1b\[0m', l):
        f,g,b,fr,fg,fb,ch = m.groups()
        res.append((f,g,b,fr,fg,fb,ch))
    return res
def clean(l):
    return re.sub(r'\x1b\[38;2;([0-9]+);([0-9]+);([0-9]+);48;2;([0-9]+);([0-9]+);([0-9]+)m(.)\x1b\[0m', lambda m:'('+m.group(6)+')', l)
for i,l in enumerate(lines):
    bl=blocks(l)
    print(i, 'nb=%d'%len(bl), repr(clean(l)))
    if bl:
        s=[]
        for f,g,b,fr,fg,fb,ch in bl:
            same = (f,g,b)==(fr,fg,fb)
            s.append('C' if (same and ch==' ') else ('D' if ch=='\u2580' else '?'))
        print('      ', ''.join(s))
EOF"}

