{"command": "cd /workspace && args=""; for i in $(seq 255 -1 0); do args="$args $(printf '%02x%02x%02x' $i $i $((i+1)))"; done; ./executable sort-by luminance $args | ./executable format hex | tr '\n' ' ' > /tmp/lum_sort.txt; python3 - <<'EOF'
import math
exec(open('/tmp/an2.py').read())
vals=[int(x[1:3],16) for x in open('/tmp/lum_sort.txt').read().split()]
def lum2(r,g,b):
    return 0.2126729*lin(r)+0.7151522*lin(g)+0.0721750*lin(b)
groups=[]
cur=[vals[0]]
for v in vals[1:]:
    if v<cur[-1]: cur.append(v)
    else: groups.append(cur); cur=[v]
groups.append(cur)
print('n groups',len(groups))
bad=0
for g in groups:
    lo,hi=min(g),max(g)
    # check that all have same floor(lum*1000)
    ks=set(math.floor(lum2(v,v,v+1)*1000) for v in g)
    if len(ks)!=1: bad+=1; print('BAD group',g[:5],'...',ks)
print('bad',bad)
print([ (min(g),max(g),math.floor(lum2(min(g),min(g),min(g)+1)*1000)) for g in groups][:15])
EOF"}

