import subprocess
def q(colors, fmt='ansi-8bit-value'):
    inp='\n'.join('%02x%02x%02x'%c for c in colors)+'\n'
    p=subprocess.run(['./executable','format',fmt],input=inp.encode(),capture_output=True,cwd='/workspace')
    return [int(x) for x in p.stdout.decode().split()]
for name,gen in [('r',(lambda v:(v,0,0))),('g',(lambda v:(0,v,0))),('b',(lambda v:(0,0,v))),
                 ('rr',(lambda v:(v,v,0))),('rg',(lambda v:(v,0,v))),('gb',(lambda v:(0,v,v)))]:
    res=q([gen(v) for v in range(256)])
    prev=None; bounds=[]
    for v,x in enumerate(res):
        if prev is not None and x!=prev: bounds.append((v-1,v,prev,x))
        prev=x
    print(name, bounds)
EOF"}

