// Color representation and conversions (reimplemented from scratch).

pub const EPS: f64 = 216.0 / 24389.0;
pub const KAPPA: f64 = 24389.0 / 27.0;

#[derive(Clone, Copy, Debug)]
pub struct Color {
    pub r: f64, // 0..1
    pub g: f64,
    pub b: f64,
    pub a: f64, // 0..1
}

pub fn linearize(v: f64) -> f64 {
    if v <= 0.04045 {
        v / 12.92
    } else {
        ((v + 0.055) / 1.055).powf(2.4)
    }
}

pub fn delinearize(v: f64) -> f64 {
    if v <= 0.0031308 {
        12.92 * v
    } else {
        1.055 * v.powf(1.0 / 2.4) - 0.055
    }
}

// sRGB -> XYZ matrix (as used by pastel)
const M_SRGB_XYZ: [[f64; 3]; 3] = [
    [0.4124, 0.3576, 0.1805],
    [0.2126, 0.7152, 0.0722],
    [0.0193, 0.1192, 0.9505],
];
const WHITE: [f64; 3] = [0.95047, 1.0, 1.08883];

// OkLab matrices
const M_OKLAB_LMS: [[f64; 3]; 3] = [
    [0.4122214708, 0.5363325363, 0.0514459929],
    [0.2119035197, 0.6805964159, 0.1075001979],
    [0.0883024629, 0.2817187464, 0.6299787007],
];
const M_OKLAB_LAB: [[f64; 3]; 3] = [
    [0.2104542553, 0.7936177850, -0.0040720468],
    [1.9779984951, -2.4285922050, 0.4505937099],
    [0.0259040371, 0.7827717662, -0.8086757660],
];
const M_OKLAB_LMS_INV: [[f64; 3]; 3] = [
    [1.0, 0.3963377774, 0.2158037530],
    [1.0, -0.1055613458, -0.0638541728],
    [1.0, -0.0894841775, -1.2914855480],
];

fn mat_inv(m: [[f64; 3]; 3]) -> [[f64; 3]; 3] {
    let [a, b, c] = m[0];
    let [d, e, f] = m[1];
    let [g, h, i] = m[2];
    let det = a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
    [
        [(e * i - f * h) / det, (c * h - b * i) / det, (b * f - c * e) / det],
        [(f * g - d * i) / det, (a * i - c * g) / det, (c * d - a * f) / det],
        [(d * h - e * g) / det, (b * g - a * h) / det, (a * e - b * d) / det],
    ]
}

lazy_static_mat!(M_SRGB_XYZ_INV = mat_inv(M_SRGB_XYZ));
lazy_static_mat!(M_OKLAB_LAB_INV = mat_inv(M_OKLAB_LAB));

macro_rules! lazy_static_mat {
    ($name:ident = $expr:expr) => {
        fn $name() -> [[f64; 3]; 3] {
            use std::sync::OnceLock;
            static CELL: OnceLock<[[f64; 3]; 3]> = OnceLock::new();
            *CELL.get_or_init(|| $expr)
        }
    };
}

pub fn cbrt(x: f64) -> f64 {
    if x < 0.0 {
        -(-x).powf(1.0 / 3.0)
    } else {
        x.powf(1.0 / 3.0)
    }
}

#[derive(Clone, Copy, Debug)]
pub struct Lab {
    pub l: f64,
    pub a: f64,
    pub b: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct LCh {
    pub l: f64,
    pub c: f64,
    pub h: f64, // degrees 0..360
}

#[derive(Clone, Copy, Debug)]
pub struct Hsl {
    pub h: f64, // degrees 0..360
    pub s: f64,
    pub l: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct Hsv {
    pub h: f64,
    pub s: f64,
    pub v: f64,
}

impl Color {
    pub fn new(r: f64, g: f64, b: f64) -> Self {
        Color { r, g, b, a: 1.0 }
    }
    pub fn from_gray(v: f64) -> Self {
        Color::new(v, v, v)
    }
    pub fn from_rgb8(r: u8, g: u8, b: u8) -> Self {
        Color::new(r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0)
    }

    pub fn clamp01(x: f64) -> f64 {
        x.max(0.0).min(1.0)
    }

    /// Round to nearest u8 (as done when converting to RGB)
    pub fn to_rgb8(&self) -> (u8, u8, u8) {
        (
            (self.r * 255.0 + 0.5).floor().clamp(0.0, 255.0) as u8,
            (self.g * 255.0 + 0.5).floor().clamp(0.0, 255.0) as u8,
            (self.b * 255.0 + 0.5).floor().clamp(0.0, 255.0) as u8,
        )
    }

    pub fn hsl(&self) -> Hsl {
        let r = self.r;
        let g = self.g;
        let b = self.b;
        let max = r.max(g).max(b);
        let min = r.min(g).min(b);
        let l = (max + min) / 2.0;
        let d = max - min;
        let s = if d == 0.0 { 0.0 } else { d / (1.0 - (2.0 * l - 1.0).abs()) };
        let h = if d == 0.0 {
            0.0
        } else if max == r {
            60.0 * (((g - b) / d) % 6.0)
        } else if max == g {
            60.0 * ((b - r) / d + 2.0)
        } else {
            60.0 * ((r - g) / d + 4.0)
        };
        Hsl { h: wrap_degrees(h), s, l }
    }

    pub fn hsv(&self) -> Hsv {
        let max = self.r.max(self.g).max(self.b);
        let min = self.r.min(self.g).min(self.b);
        let d = max - min;
        let s = if max == 0.0 { 0.0 } else { d / max };
        let h = if d == 0.0 {
            0.0
        } else if max == self.r {
            60.0 * (((self.g - self.b) / d) % 6.0)
        } else if max == self.g {
            60.0 * ((self.b - self.r) / d + 2.0)
        } else {
            60.0 * ((self.r - self.g) / d + 4.0)
        };
        Hsv { h: wrap_degrees(h), s, v: max }
    }

    pub fn xyz(&self) -> [f64; 3] {
        let r = linearize(self.r);
        let g = linearize(self.g);
        let b = linearize(self.b);
        let mut out = [0.0; 3];
        for (i, row) in M_SRGB_XYZ.iter().enumerate() {
            out[i] = row[0] * r + row[1] * g + row[2] * b;
        }
        out
    }

    pub fn lab(&self) -> Lab {
        let xyz = self.xyz();
        let fx = f_f(xyz[0] / WHITE[0]);
        let fy = f_f(xyz[1] / WHITE[1]);
        let fz = f_f(xyz[2] / WHITE[2]);
        Lab {
            l: 116.0 * fy - 16.0,
            a: 500.0 * (fx - fy),
            b: 200.0 * (fy - fz),
        }
    }

    pub fn lch(&self) -> LCh {
        let lab = self.lab();
        let c = (lab.a * lab.a + lab.b * lab.b).sqrt();
        let mut h = lab.b.atan2(lab.a).to_degrees();
        if h < 0.0 {
            h += 360.0;
        }
        LCh { l: lab.l, c, h }
    }

    pub fn oklab(&self) -> [f64; 3] {
        let r = linearize(self.r);
        let g = linearize(self.g);
        let b = linearize(self.b);
        let mut lms = [0.0; 3];
        for (i, row) in M_OKLAB_LMS.iter().enumerate() {
            lms[i] = row[0] * r + row[1] * g + row[2] * b;
        }
        let p: Vec<f64> = lms.iter().map(|x| cbrt(*x)).collect();
        let mut out = [0.0; 3];
        for (i, row) in M_OKLAB_LAB.iter().enumerate() {
            out[i] = row[0] * p[0] + row[1] * p[1] + row[2] * p[2];
        }
        out
    }

    pub fn oklch(&self) -> (f64, f64, f64) {
        let ok = self.oklab();
        let c = (ok[1] * ok[1] + ok[2] * ok[2]).sqrt();
        let mut h = ok[2].atan2(ok[1]).to_degrees();
        if h < 0.0 {
            h += 360.0;
        }
        (ok[0], c, h)
    }

    /// WCAG relative luminance
    pub fn luminance(&self) -> f64 {
        let r = linearize(self.r);
        let g = linearize(self.g);
        let b = linearize(self.b);
        0.2126729 * r + 0.7151522 * g + 0.0721750 * b
    }

    /// Perceived brightness
    pub fn brightness(&self) -> f64 {
        0.299 * self.r + 0.587 * self.g + 0.114 * self.b
    }

    pub fn cmyk(&self) -> [f64; 4] {
        let k = 1.0 - self.r.max(self.g).max(self.b);
        if k >= 1.0 {
            return [0.0, 0.0, 0.0, 1.0];
        }
        let c = (1.0 - self.r - k) / (1.0 - k);
        let m = (1.0 - self.g - k) / (1.0 - k);
        let y = (1.0 - self.b - k) / (1.0 - k);
        [c, m, y, k]
    }

    pub fn from_hsl(h: f64, s: f64, l: f64) -> Color {
        let h = wrap_degrees(h);
        let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
        let hp = h / 60.0;
        let x = c * (1.0 - (hp % 2.0 - 1.0).abs());
        let (r1, g1, b1) = match hp.floor() as i64 {
            0 => (c, x, 0.0),
            1 => (x, c, 0.0),
            2 => (0.0, c, x),
            3 => (0.0, x, c),
            4 => (x, 0.0, c),
            _ => (c, 0.0, x),
        };
        let m = l - c / 2.0;
        Color::new(r1 + m, g1 + m, b1 + m)
    }

    pub fn from_hsv(h: f64, s: f64, v: f64) -> Color {
        let h = wrap_degrees(h);
        let c = v * s;
        let hp = h / 60.0;
        let x = c * (1.0 - (hp % 2.0 - 1.0).abs());
        let (r1, g1, b1) = match hp.floor() as i64 {
            0 => (c, x, 0.0),
            1 => (x, c, 0.0),
            2 => (0.0, c, x),
            3 => (0.0, x, c),
            4 => (x, 0.0, c),
            _ => (c, 0.0, x),
        };
        let m = v - c;
        Color::new(r1 + m, g1 + m, b1 + m)
    }

    pub fn from_lab(lab: Lab) -> Color {
        Color::from_xyz(lab_to_xyz(lab))
    }

    pub fn from_lch(lch: LCh) -> Color {
        let h = lch.h.to_radians();
        Color::from_lab(Lab {
            l: lch.l,
            a: lch.c * h.cos(),
            b: lch.c * h.sin(),
        })
    }

    pub fn from_xyz(xyz: [f64; 3]) -> Color {
        let minv = M_SRGB_XYZ_INV();
        let lin = [
            minv[0][0] * xyz[0] + minv[0][1] * xyz[1] + minv[0][2] * xyz[2],
            minv[1][0] * xyz[0] + minv[1][1] * xyz[1] + minv[1][2] * xyz[2],
            minv[2][0] * xyz[0] + minv[2][1] * xyz[1] + minv[2][2] * xyz[2],
        ];
        Color::new(
            delinearize(clamp01(lin[0])),
            delinearize(clamp01(lin[1])),
            delinearize(clamp01(lin[2])),
        )
    }

    pub fn from_oklab(l: f64, a: f64, b: f64) -> Color {
        let lms = [
            M_OKLAB_LMS_INV[0][0] * l + M_OKLAB_LMS_INV[0][1] * a + M_OKLAB_LMS_INV[0][2] * b,
            M_OKLAB_LMS_INV[1][0] * l + M_OKLAB_LMS_INV[1][1] * a + M_OKLAB_LMS_INV[1][2] * b,
            M_OKLAB_LMS_INV[2][0] * l + M_OKLAB_LMS_INV[2][1] * a + M_OKLAB_LMS_INV[2][2] * b,
        ];
        let l3 = lms[0] * lms[0] * lms[0];
        let m3 = lms[1] * lms[1] * lms[1];
        let s3 = lms[2] * lms[2] * lms[2];
        let inv = M_OKLAB_LMS_MAT_INV();
        let lin = [
            inv[0][0] * l3 + inv[0][1] * m3 + inv[0][2] * s3,
            inv[1][0] * l3 + inv[1][1] * m3 + inv[1][2] * s3,
            inv[2][0] * l3 + inv[2][1] * m3 + inv[2][2] * s3,
        ];
        Color::new(
            delinearize(clamp01(lin[0])),
            delinearize(clamp01(lin[1])),
            delinearize(clamp01(lin[2])),
        )
    }

    pub fn from_oklch(l: f64, c: f64, h: f64) -> Color {
        let hr = h.to_radians();
        Color::from_oklab(l, c * hr.cos(), c * hr.sin())
    }
}

lazy_static_mat2!(M_OKLAB_LMS_MAT_INV = mat_inv(M_OKLAB_LMS));

macro_rules! lazy_static_mat2 {
    ($name:ident = $expr:expr) => {
        fn $name() -> [[f64; 3]; 3] {
            use std::sync::OnceLock;
            static CELL: OnceLock<[[f64; 3]; 3]> = OnceLock::new();
            *CELL.get_or_init(|| $expr)
        }
    };
}

pub fn f_f(t: f64) -> f64 {
    if t > EPS {
        t.powf(1.0 / 3.0)
    } else {
        (KAPPA * t + 16.0) / 116.0
    }
}

pub fn lab_to_xyz(lab: Lab) -> [f64; 3] {
    let fy = (lab.l + 16.0) / 116.0;
    let fx = fy + lab.a / 500.0;
    let fz = fy - lab.b / 200.0;
    let fx3 = fx * fx * fx;
    let fy3 = fy * fy * fy;
    let fz3 = fz * fz * fz;
    let x = if fx3 > EPS { WHITE[0] * fx3 } else { WHITE[0] * (116.0 * fx - 16.0) / KAPPA };
    let y = if fy3 > EPS { WHITE[1] * fy3 } else { WHITE[1] * (116.0 * fy - 16.0) / KAPPA };
    let z = if fz3 > EPS { WHITE[2] * fz3 } else { WHITE[2] * (116.0 * fz - 16.0) / KAPPA };
    [x, y, z]
}

pub fn wrap_degrees(h: f64) -> f64 {
    let mut h = h % 360.0;
    if h < 0.0 {
        h += 360.0;
    }
    h
}
RSEOF
