    [0.2119035197, 0.6805964159, 0.1075001979],
    [0.0883024629, 0.2817187464, 0.6299787007],
];
const M_OKLAB_LAB: [[f64; 3]; 3] = [
    [0.2104542553, 0.7936177850, -0.0040720468],
    [1.9779984951, -2.4285922050, 0.4505937099],
    [0.0259040371, 0.7827717662, -0.8086757660],
];

fn oklab_of(r: f64, g: f64, b: f64) -> [f64; 3] {
    let r = linearize(r);
    let g = linearize(g);
    let b = linearize(b);
    let p = [
        cbrt(M_OKLAB_LMS[0][0] * r + M_OKLAB_LMS[0][1] * g + M_OKLAB_LMS[0][2] * b),
        cbrt(M_OKLAB_LMS[1][0] * r + M_OKLAB_LMS[1][1] * g + M_OKLAB_LMS[1][2] * b),
        cbrt(M_OKLAB_LMS[2][0] * r + M_OKLAB_LMS[2][1] * g + M_OKLAB_LMS[2][2] * b),
    ];
    let mut out = [0.0; 3];
    for (i, row) in M_OKLAB_LAB.iter().enumerate() {
        out[i] = row[0] * p[0] + row[1] * p[1] + row[2] * p[2];
    }
    out
}

pub fn palette_rgb(index: usize) -> (u8, u8, u8) {
    if index < 16 {
        let base: [(u8, u8, u8); 16] = [
