def jaro(a,b):
    la,lb=len(a),len(b)
    if la==0 and lb==0: return 1.0
    md=max(la,lb)//2-1
    if md<0: md=0
    fa=[False]*la; fb=[False]*lb; m=0
    for i in range(la):
        lo=max(0,i-md); hi=min(lb,i+md+1)
        for j in range(lo,hi):
            if not fb[j] and a[i]==b[j]:
                fa[i]=fb[j]=True; m+=1; break
    if m==0: return 0.0
    t=0; k=0
    for i in range(la):
        if fa[i]:
            while not fb[k]: k+=1
            if a[i]!=b[k]: t+=1
            k+=1
    t//=2
    return (m/la + m/lb + (m-t)/m)/3
def jw(a,b):
    j=jaro(a,b)
    if j>0.7:
        p=0
        for x,y in zip(a,b):
            if x==y: p+=1
            else: break
        if p<4: return j+p*0.1*(1-j)
    return j
cmds="color colorblind colorcheck complement darken desaturate distinct format gradient gray lighten list mix paint pick random rotate saturate set sort-by textcolor to-gray".split()
for t in "xyz colr formatt rotatee colors textcolorX sortby set1 gray1 frobnicate".split():
    s=[(round(jw(t,c),3),c) for c in cmds if jw(t,c)>0.7]
    print(t, sorted(s,reverse=True))
EOF"}

