// Command line parsing (clap-like behaviour).

use crate::{Ctx, ColorMode};

pub struct ArgError {
    pub msg: String,
    pub code: u8,
}

impl ArgError {
    pub fn new(msg: String) -> Self {
        ArgError { msg, code: 2 }
    }
}

fn perr(s: &str) -> ArgError {
    ArgError { msg: s.to_string(), code: 1 }
}

const SUBCOMMANDS: &[&str] = &[
    "color",
    "colorblind",
    "colorcheck",
    "complement",
    "darken",
    "desaturate",
    "distinct",
    "format",
    "gradient",
    "gray",
    "help",
    "lighten",
    "list",
    "mix",
    "paint",
    "pick",
    "random",
    "rotate",
    "saturate",
    "set",
    "sort-by",
    "textcolor",
    "to-gray",
    // hidden aliases (not listed in help, used for suggestions)
    "colour",
    "sort",
    "take",
    "show",
    "display",
];

pub const VISIBLE_SUBCOMMANDS: &[&str] = &[
    "color",
    "colorblind",
    "colorcheck",
    "complement",
    "darken",
    "desaturate",
    "distinct",
    "format",
    "gradient",
    "gray",
    "help",
    "lighten",
    "list",
    "mix",
    "paint",
    "pick",
    "random",
    "rotate",
    "saturate",
    "set",
    "sort-by",
    "textcolor",
    "to-gray",
];

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (la, lb) = (a.len(), b.len());
    if la == 0 && lb == 0 {
        return 1.0;
    }
    let md = if la.max(lb) < 2 { 0 } else { la.max(lb) / 2 - 1 };
    let mut fa = vec![false; la];
    let mut fb = vec![false; lb];
    let mut m = 0usize;
    for i in 0..la {
        let lo = i.saturating_sub(md);
        let hi = (i + md + 1).min(lb);
        for j in lo..hi {
            if !fb[j] && a[i] == b[j] {
                fa[i] = true;
                fb[j] = true;
                m += 1;
                break;
            }
        }
    }
    if m == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut k = 0usize;
    for i in 0..la {
        if fa[i] {
            while !fb[k] {
                k += 1;
            }
            if a[i] != b[k] {
                t += 1;
            }
            k += 1;
        }
    }
    t /= 2;
    (m as f64 / la as f64 + m as f64 / lb as f64 + (m - t) as f64 / m as f64) / 3.0
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    if j > 0.7 {
        let mut p = 0usize;
        for (x, y) in a.chars().zip(b.chars()) {
            if x == y {
                p += 1;
            } else {
                break;
            }
        }
        if p < 4 {
            return j + p as f64 * 0.1 * (1.0 - j);
        }
    }
    j
}

pub fn help_text(prog: &str, s: &str) -> String {
    s.replace("executable", prog)
}

fn unrecognized_subcommand(prog: &str, name: &str) -> ArgError {
    let mut msg = format!("error: unrecognized subcommand '{}'\n", name);
    let mut cands: Vec<(f64, &str)> = SUBCOMMANDS
        .iter()
        .map(|c| (jaro_winkler(name, c), *c))
        .filter(|(s, _)| *s > 0.7)
        .collect();
    cands.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap().then(a.1.cmp(b.1)));
    if cands.len() == 1 {
        msg.push_str(&format!(
            "\n  tip: a similar subcommand exists: '{}'\n",
            cands[0].1
        ));
    } else if cands.len() > 1 {
        let list: Vec<String> = cands.iter().map(|(_, c)| format!("'{}'", c)).collect();
        msg.push_str(&format!(
            "\n  tip: some similar subcommands exist: {}\n",
            list.join(", ")
        ));
    }
    msg.push_str(&format!(
        "\nUsage: {} [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n",
        prog
    ));
    ArgError::new(msg)
}

fn unexpected_argument(prog: &str, usage: &str, a: &str) -> ArgError {
    ArgError::new(format!(
        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {}\n\nFor more information, try '--help'.\n",
        a, a, a, help_text(prog, usage)
    ))
}

fn missing_required(prog: &str, usage: &str, args: &[&str]) -> ArgError {
    let mut m = String::from("error: the following required arguments were not provided:\n");
    for a in args {
        m.push_str(&format!("  {}\n", a));
    }
    m.push_str(&format!(
        "\nUsage: {}\n\nFor more information, try '--help'.\n",
        help_text(prog, usage)
    ));
    ArgError::new(m)
}

fn invalid_value(val: &str, arg: &str, possible: &[&str]) -> ArgError {
    ArgError::new(format!(
        "error: invalid value '{}' for '{}'\n  [possible values: {}]\n\nFor more information, try '--help'.\n",
        val,
        arg,
        possible.join(", ")
    ))
}

fn value_required(name: &str, possible: Option<&[&str]>) -> ArgError {
    let mut m = format!(
        "error: a value is required for '{}' but none was supplied\n",
        name
    );
    if let Some(p) = possible {
        m.push_str(&format!("  [possible values: {}]\n", p.join(", ")));
    }
    m.push_str("\nFor more information, try '--help'.\n");
    ArgError::new(m)
}

pub enum ColorsInput {
    None,
    List(Vec<String>),
}

pub struct Parsed {
    pub cmd: String,
    pub positional: Vec<String>,
    pub colors: Vec<String>,
    pub count: Option<usize>,
    pub number: usize,
    pub strategy: Option<String>,
    pub colorspace: String,
    pub fraction: f64,
    pub metric: String,
    pub verbose: bool,
    pub sort: String,
    pub prop: String,
    pub value: String,
    pub on: Option<String>,
    pub bold: bool,
    pub italic: bool,
    pub underline: bool,
    pub no_newline: bool,
    pub cblind: String,
    pub format: String,
    pub set_prop: String,
    pub set_value: f64,
    pub count_arg: Option<usize>,
}

fn parse_num(s: &str) -> Result<f64, ArgError> {
    s.trim()
        .parse::<f64>()
        .map_err(|_| perr(&format!("Could not parse number '{}'", s)))
}

pub fn run(prog: &str, args: &[String]) -> Result<(), ArgError> {
    let mut mode = ColorMode::Auto;
    let mut i = 0usize;
    let mut usage_main = "executable [OPTIONS] <COMMAND>";
    // global options
    let mut cmd: Option<String> = None;
    while i < args.len() {
        let a = &args[i];
        if a == "--" {
            i += 1;
            continue;
        }
        if a.starts_with("--") {
            let (name, val) = match a.split_once('=') {
                Some((n, v)) => (n, Some(v.to_string())),
                None => (a.as_str(), None),
            };
            match name {
                "--help" => {
                    print!("{}", help_text(prog, crate::help::MAIN_HELP));
                    return Ok(());
                }
                "--version" => {
                    println!("{}", crate::VERSION);
                    return Ok(());
                }
                "--force-color" => mode = ColorMode::TrueColor,
                "--color-mode" | "--mode" => {
                    let v = match val {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() {
                                i += 1;
                                args[i].clone()
                            } else {
                                return Err(value_required("--color-mode <mode>", Some(&["24bit", "8bit", "off", "auto"])));
