                        "off" => ColorMode::Off,
                        "auto" => ColorMode::Auto,
                        _ => return Err(invalid_value(&v, "--color-mode <mode>", &["24bit", "8bit", "off", "auto"])),
                    };
                }
                "--color-picker" => {
                    let _v = match val {
                        Some(v) => v,
                        None => {
                            if i + 1 < args.len() {
                                i += 1;
                                args[i].clone()
                            } else {
                                return Err(value_required("--color-picker <color-picker>", Some(&["gpick", "xcolor", "wcolor", "grabc", "colorpicker", "chameleon", "kcolorchooser", "zenity", "yad", "hyprpicker", "gdbus"])));
                            }
                        }
                    };
                }
                _ => {
                    return Err(unexpected_argument(prog, usage_main, a));
                }
            }
            i += 1;
            continue;
        }
        if a.starts_with('-') && a.len() > 1 {
