                "-h" => {
                    print!("{}", help_text(prog, crate::help::MAIN_SHORT_HELP));
                    return Ok(());
                }
                "-V" => {
                    println!("{}", crate::VERSION);
                    return Ok(());
                }
                "-f" => mode = ColorMode::TrueColor,
                "-m" => {
                    if i + 1 < args.len() {
                        i += 1;
                        let v = args[i].clone();
                        mode = match v.as_str() {
                            "24bit" => ColorMode::TrueColor,
                            "8bit" => ColorMode::Ansi8,
                            "off" => ColorMode::Off,
                            "auto" => ColorMode::Auto,
                            _ => return Err(invalid_value(&v, "--color-mode <mode>", &["24bit", "8bit", "off", "auto"])),
                        };
                    } else {
                        return Err(value_required("--color-mode <mode>", Some(&["24bit", "8bit", "off", "auto"])));
                    }
                }
                _ => return Err(unexpected_argument(prog, usage_main, a)),
            }
            i += 1;
            continue;
        }
        cmd = Some(a.clone());
        i += 1;
        break;
    }
    let cmd = match cmd {
        Some(c) => c,
        None => {
            eprint!("{}", help_text(prog, crate::help::MAIN_HELP));
            return Err(ArgError { msg: String::new(), code: 2 });
        }
    };
