// Command line parsing (clap-like behaviour).

use crate::{Ctx, ColorMode};

pub struct ArgError {
    pub msg: String,
    pub code: u8,
}

impl ArgError {
    pub fn new(msg: String) -> Self {
        ArgError { msg, code: 2 }
    }
}

fn perr(s: &str) -> ArgError {
    ArgError { msg: s.to_string(), code: 1 }
}

const SUBCOMMANDS: &[&str] = &[
    "color",
    "colorblind",
    "colorcheck",
    "complement",
    "darken",
    "desaturate",
    "distinct",
    "format",
