    pub no_newline: bool,
    pub cblind: String,
    pub format: String,
    pub set_prop: String,
    pub set_value: f64,
    pub count_arg: Option<usize>,
}

fn parse_num(s: &str) -> Result<f64, ArgError> {
    s.trim()
        .parse::<f64>()
        .map_err(|_| perr(&format!("Could not parse number '{}'", s)))
}

