                        "Lab" | "LCh" | "RGB" | "HSL" | "OkLab" => v,
                        _ => return Err(invalid_value(&v, "--colorspace <name>", &["Lab", "LCh", "RGB", "HSL", "OkLab"])),
                    };
                }
                ("mix", "--fraction") | ("mix", "-f") => {
                    let v = need(None)?;
                    p.fraction = parse_num(&v)?;
                }
                ("list", "--sort") | ("list", "-s") => {
                    let v = need(Some(&["brightness", "luminance", "hue", "chroma", "random"]))?;
                    p.sort = match v.as_str() {
                        "brightness" | "luminance" | "hue" | "chroma" | "random" => v,
                        _ => return Err(invalid_value(&v, "--sort <sort-order>", &["brightness", "luminance", "hue", "chroma", "random"])),
                    };
                }
                ("random", "--strategy") | ("random", "-s") => {
                    let v = need(None)?;
                    p.strategy = Some(v);
                }
                ("random", "--number") | ("random", "-n") => {
                    let v = need(None)?;
                    p.number = parse_num(&v)? as usize;
                }
                ("paint", "--on") | ("paint", "-o") => {
                    p.on = Some(need(None)?);
                }
                ("paint", "--bold") | ("paint", "-b") => p.bold = true,
                ("paint", "--italic") | ("paint", "-i") => p.italic = true,
                ("paint", "--underline") | ("paint", "-u") => p.underline = true,
                ("paint", "--no-newline") | ("paint", "-n") => p.no_newline = true,
                _ => return Err(unexpected_argument(prog, &usage, &a)),
            }
            i += 1;
            continue;
        }
        if a.starts_with('-') && a.len() > 1 {
            match (canonical.as_str(), a.as_str()) {
                ("distinct", "-v") => p.verbose = true,
                ("distinct", "-m") => {
                    if i + 1 < args.len() {
                        i += 1;
                        let v = args[i].clone();
                        p.metric = match v.as_str() {
                            "CIEDE2000" | "CIE76" => v,
                            _ => return Err(invalid_value(&v, "--metric <name>", &["CIEDE2000", "CIE76"])),
                        };
                    } else {
                        return Err(value_required("--metric <name>", Some(&["CIEDE2000", "CIE76"])));
                    }
                }
                ("gradient", "-n") | ("random", "-n") => {
                    if i + 1 < args.len() {
                        i += 1;
                        p.number = parse_num(&args[i])? as usize;
                    } else {
                        return Err(value_required("--number <count>", None));
                    }
                }
                ("gradient", "-s") | ("mix", "-s") | ("list", "-s") | ("random", "-s") => {
                    if i + 1 < args.len() {
                        i += 1;
                        let v = args[i].clone();
                        let poss: &[&str] = &["Lab", "LCh", "RGB", "HSL", "OkLab"];
                        if canonical == "list" {
                            let p2: &[&str] = &["brightness", "luminance", "hue", "chroma", "random"];
                            p.sort = match v.as_str() {
                                "brightness" | "luminance" | "hue" | "chroma" | "random" => v,
                                _ => return Err(invalid_value(&v, "--sort <sort-order>", p2)),
                            };
                        } else if canonical == "random" {
                            p.strategy = Some(v);
                        } else {
                            p.colorspace = match v.as_str() {
                                "Lab" | "LCh" | "RGB" | "HSL" | "OkLab" => v,
                                _ => return Err(invalid_value(&v, "--colorspace <name>", poss)),
                            };
                        }
                    } else {
                        return Err(value_required("--colorspace <name>", Some(&["Lab", "LCh", "RGB", "HSL", "OkLab"])));
                    }
                }
                ("mix", "-f") => {
                    if i + 1 < args.len() {
                        i += 1;
                        p.fraction = parse_num(&args[i])?;
                    } else {
                        return Err(value_required("--fraction <fraction>", None));
                    }
                }
                ("paint", "-o") => {
                    if i + 1 < args.len() {
                        i += 1;
                        p.on = Some(args[i].clone());
                    } else {
                        return Err(value_required("--on <bg-color>", None));
                    }
                }
                ("paint", "-b") => p.bold = true,
                ("paint", "-i") => p.italic = true,
                ("paint", "-u") => p.underline = true,
                ("paint", "-n") => p.no_newline = true,
                ("-h", _) | (_, "-h") if false => {}
                _ => {
                    if a == "-h" {
                        print!(
                            "{}",
                            help_text(prog, crate::help::SHORT_HELP_BY_NAME(&canonical))
                        );
                        return Ok(());
                    }
                    return Err(unexpected_argument(prog, &usage, &a));
                }
            }
            i += 1;
            continue;
        }
        pos.push(a);
        i += 1;
    }
    p.positional = pos;

    // interpret positionals per command
    let read_colors = |pos: &[String], start: usize| -> Vec<String> {
        let mut v: Vec<String> = pos.iter().skip(start).cloned().collect();
        if v.is_empty() {
            // read from stdin
            use std::io::Read;
            let mut s = String::new();
            if std::io::stdin().read_to_string(&mut s).is_ok() {
                for line in s.lines() {
                    let l = line.trim();
                    if !l.is_empty() {
                        v.push(l.to_string());
                    }
                }
            }
        }
        v
    };
    match canonical.as_str() {
        "color" | "complement" | "textcolor" | "to-gray" => {
            p.colors = read_colors(&p.positional, 0);
        }
        "colorblind" => {
            if p.positional.is_empty() {
                return Err(missing_required(prog, &usage, &["<type>"]));
            }
            p.cblind = p.positional[0].clone();
            if !["prot", "deuter", "trit"].contains(&p.cblind.as_str()) {
                return Err(invalid_value(&p.cblind, "<type>", &["prot", "deuter", "trit"]));
            }
            p.colors = read_colors(&p.positional, 1);
        }
        "darken" | "desaturate" | "lighten" | "saturate" => {
            if p.positional.is_empty() {
                let nm = match canonical.as_str() {
                    "rotate" => "<degrees>",
                    _ => "<amount>",
                };
                return Err(missing_required(prog, &usage, &[nm]));
            }
            p.set_value = parse_num(&p.positional[0])?;
            p.colors = read_colors(&p.positional, 1);
        }
        "rotate" => {
            if p.positional.is_empty() {
                return Err(missing_required(prog, &usage, &["<degrees>"]));
            }
            p.set_value = parse_num(&p.positional[0])?;
            p.colors = read_colors(&p.positional, 1);
        }
        "distinct" => {
            if !p.positional.is_empty() {
                p.count_arg = Some(parse_num(&p.positional[0])? as usize);
                p.colors = read_colors(&p.positional, 1);
            } else {
                p.colors = read_colors(&p.positional, 0);
            }
        }
        "format" => {
            if !p.positional.is_empty() {
                let t = p.positional[0].clone();
                if crate::commands::FORMATS.contains(&t.as_str()) {
                    p.format = t;
                    p.colors = read_colors(&p.positional, 1);
                } else {
                    return Err(invalid_value(&t, "[type]", crate::commands::FORMATS));
                }
            } else {
                p.colors = read_colors(&p.positional, 0);
            }
        }
        "gradient" => {
            if p.positional.is_empty() {
                return Err(missing_required(prog, &usage, &["<color>..."]));
            }
            p.colors = read_colors(&p.positional, 0);
        }
        "gray" => {
            if p.positional.is_empty() {
                return Err(missing_required(prog, &usage, &["<lightness>"]));
            }
            p.set_value = parse_num(&p.positional[0])?;
        }
        "mix" => {
            p.colors = read_colors(&p.positional, 0);
        }
        "paint" => {
            if p.positional.is_empty() {
                return Err(missing_required(prog, &usage, &["<color>"]));
            }
            p.colors = read_colors(&p.positional, 0);
        }
        "pick" => {
            if !p.positional.is_empty() {
                p.count_arg = Some(parse_num(&p.positional[0])? as usize);
            }
        }
        "random" => {}
        "set" => {
            if p.positional.len() < 2 {
                let missing: Vec<&str> = if p.positional.is_empty() {
                    vec!["<property>", "<value>"]
                } else {
                    vec!["<value>"]
                };
                return Err(missing_required(prog, &usage, &missing));
            }
            let props: Vec<&str> = vec![
                "lightness",
                "hue",
                "chroma",
                "lab-a",
                "lab-b",
                "oklab-l",
                "oklab-a",
                "oklab-b",
                "red",
                "green",
                "blue",
                "hsl-hue",
                "hsl-saturation",
                "hsl-lightness",
                "alpha",
            ];
            if !props.contains(&p.positional[0].as_str()) {
                return Err(invalid_value(&p.positional[0], "<property>", &props));
            }
            p.set_prop = p.positional[0].clone();
            p.value = p.positional[1].clone();
            p.set_value = parse_num(&p.value)?;
            p.colors = read_colors(&p.positional, 2);
        }
        "sort-by" => {
            let orders: Vec<&str> = vec!["brightness", "luminance", "hue", "chroma", "random"];
            if !p.positional.is_empty() && orders.contains(&p.positional[0].as_str()) {
                p.sort = p.positional[0].clone();
                p.colors = read_colors(&p.positional, 1);
            } else if !p.positional.is_empty()
                && crate::color::parse_color(&p.positional[0]).is_some()
            {
                p.colors = read_colors(&p.positional, 0);
            } else if !p.positional.is_empty() {
                return Err(invalid_value(&p.positional[0], "[sort-order]", &orders));
            } else {
                p.colors = read_colors(&p.positional, 0);
            }
        }
        _ => {}
    }

    let ctx = Ctx {
        prog: prog.to_string(),
        mode,
    };
    crate::commands::dispatch(&ctx, &p)
}
RSEOF
echo ok"}

