/// Parse a colour specification.
pub fn parse_color(s: &str) -> Option<Color> {
    let s = s.trim();
    if s.is_empty() {
        return None;
    }
    // hex
    let hexpart = if let Some(st) = s.strip_prefix('#') {
        st
    } else {
        s
    };
    if let Some(c) = parse_hex(hexpart) {
        return Some(c);
    }
    // named
    if let Some(c) = crate::names::lookup(s) {
        return Some(c);
    }
    // functional / comma forms
    if let Some(open) = s.find('(') {
        let close = s.rfind(')');
        if let Some(cl) = close {
            if cl > open {
                let name = s[..open].trim();
                let inner = &s[open + 1..cl];
                let parts: Vec<&str> = inner.split(',').map(|x| x.trim()).collect();
                let nums: Option<Vec<f64>> = parts
                    .iter()
                    .map(|p| {
                        let p = p.trim();
                        let p = p.strip_suffix('%').unwrap_or(p);
                        p.parse::<f64>().ok()
                    })
                    .collect();
                let nums = nums?;
                let pct: Vec<bool> = parts.iter().map(|p| p.trim().ends_with('%')).collect();
                let c = parse_func(name, &nums, &pct)?;
                return Some(c);
            }
        }
        return None;
    }
    // comma separated rgb
    if s.contains(',') {
        let parts: Vec<&str> = s.split(',').map(|x| x.trim()).collect();
        if parts.len() == 3 || parts.len() == 4 {
            let nums: Option<Vec<f64>> = parts.iter().map(|p| p.trim().parse::<f64>().ok()).collect();
            let nums = nums?;
            let r = (nums[0] / 255.0).clamp(0.0, 1.0);
            let g = (nums[1] / 255.0).clamp(0.0, 1.0);
            let b = (nums[2] / 255.0).clamp(0.0, 1.0);
            let mut c = Color::new(r, g, b);
            if nums.len() == 4 {
                c.a = nums[3].clamp(0.0, 1.0);
            }
            return Some(c);
        }
        return None;
    }
    None
}

fn parse_hex(s: &str) -> Option<Color> {
    let s = s.trim();
    let ok = s.chars().all(|c| c.is_ascii_hexdigit());
    if !ok {
        return None;
    }
    let n = s.chars().count();
    let double = |d: &str| -> Option<u8> {
        let v = u32::from_str_radix(d, 16).ok()?;
        let _ = v;
        let hi = u32::from_str_radix(&d[0..1], 16).ok()?;
        Some((hi * 16 + hi) as u8)
    };
    match n {
        3 => {
            let r = double(&s[0..1])?;
            let g = double(&s[1..2])?;
            let b = double(&s[2..3])?;
            Some(Color::from_rgb8(r, g, b))
        }
        4 => {
            let r = double(&s[0..1])?;
            let g = double(&s[1..2])?;
            let b = double(&s[2..3])?;
            let a = double(&s[3..4])?;
            Some(Color {
                a: a as f64 / 255.0,
                ..Color::from_rgb8(r, g, b)
            })
        }
        6 => {
            let r = u32::from_str_radix(&s[0..2], 16).ok()? as u8;
            let g = u32::from_str_radix(&s[2..4], 16).ok()? as u8;
            let b = u32::from_str_radix(&s[4..6], 16).ok()? as u8;
            Some(Color::from_rgb8(r, g, b))
        }
        8 => {
            let r = u32::from_str_radix(&s[0..2], 16).ok()? as u8;
            let g = u32::from_str_radix(&s[2..4], 16).ok()? as u8;
            let b = u32::from_str_radix(&s[4..6], 16).ok()? as u8;
            let a = u32::from_str_radix(&s[6..8], 16).ok()? as u8;
            Some(Color {
                a: a as f64 / 255.0,
                ..Color::from_rgb8(r, g, b)
            })
        }
        _ => None,
    }
}

fn parse_func(name: &str, nums: &[f64], pct: &[bool]) -> Option<Color> {
    match name {
        "rgb" | "rgba" => {
            if nums.len() < 3 || nums.len() > 4 {
                return None;
            }
            let f = |v: f64| -> f64 { (v / 255.0).clamp(0.0, 1.0) };
            let mut c = Color::new(f(nums[0]), f(nums[1]), f(nums[2]));
            if nums.len() == 4 {
                c.a = nums[3].clamp(0.0, 1.0);
            }
            Some(c)
        }
        "hsl" | "hsla" => {
            if nums.len() < 3 || nums.len() > 4 {
                return None;
            }
            if pct.len() < 3 || !pct[1] || !pct[2] {
                return None;
            }
            let s = nums[1] / 100.0;
            let l = nums[2] / 100.0;
            if !(0.0..=1.0).contains(&s) || !(0.0..=1.0).contains(&l) {
                return None;
            }
            let mut c = Color::from_hsl(nums[0], s, l);
            if nums.len() == 4 {
                c.a = nums[3].clamp(0.0, 1.0);
            }
            Some(c)
        }
        "hsv" | "hsva" => {
            if nums.len() < 3 || nums.len() > 4 {
                return None;
            }
            if pct.len() < 3 || !pct[1] || !pct[2] {
                return None;
            }
            let s = (nums[1] / 100.0).clamp(0.0, 1.0);
            let v = (nums[2] / 100.0).clamp(0.0, 1.0);
            let mut c = Color::from_hsv(nums[0], s, v);
            if nums.len() == 4 {
                c.a = nums[3].clamp(0.0, 1.0);
            }
            Some(c)
        }
        "gray" => {
            if nums.len() != 1 || pct.is_empty() || pct[0] {
                return None;
            }
            let v = nums[0].clamp(0.0, 1.0);
            let q = (v * 255.0 + 0.5).floor() / 255.0;
            Some(Color::from_gray(q))
        }
        "lab" => {
            if nums.len() != 3 {
                return None;
            }
            Some(Color::from_lab(Lab {
                l: nums[0],
                a: nums[1],
                b: nums[2],
            }))
        }
        "lch" => {
            if nums.len() != 3 {
                return None;
            }
            Some(Color::from_lch(LCh {
                l: nums[0],
                c: nums[1],
                h: nums[2],
            }))
        }
        "oklab" => {
            if nums.len() != 3 {
                return None;
            }
            Some(Color::from_oklab(nums[0], nums[1], nums[2]))
        }
        "oklch" => {
            if nums.len() != 3 {
                return None;
            }
            Some(Color::from_oklch(nums[0], nums[1], nums[2]))
        }
        _ => None,
    }
}
RSEOF
