pub fn lookup(name: &str) -> Option<crate::color::Color> {
    let lower = name.to_ascii_lowercase();
    NAMES.iter()
        .find(|(n, _, _, _)| *n == lower)
        .map(|(_, r, g, b)| crate::color::Color::from_rgb8(*r, *g, *b))
}

pub fn nearest(color: &crate::color::Color) -> Option<(&'static str, crate::color::Color)> {
    use crate::color::Lab;
    let t = color.lab();
    let mut best: Option<(f64, &'static str, crate::color::Color)> = None;
    for (n, r, g, b) in NAMES.iter() {
        let c = crate::color::Color::from_rgb8(*r, *g, *b);
        let l = c.lab();
        let d = (t.l - l.l).powi(2) + (t.a - l.a).powi(2) + (t.b - l.b).powi(2);
        if best.is_none() || d < best.unwrap().0 {
            best = Some((d, n, c));
        }
    }
    best.map(|(_, n, c)| (n, c))
}
