// Terminal colour output and block rendering.
use crate::ansi;
use crate::color::Color;

#[derive(Clone, Copy)]
pub enum Mode {
    TrueColor,
    Ansi8,
    Off,
}

pub fn detect_mode(force: Option<Mode>) -> Mode {
    if let Some(m) = force {
        return m;
    }
    if std::env::var_os("NO_COLOR").is_some() {
        return Mode::Off;
    }
    use std::io::IsTerminal;
    if !std::io::stdout().is_terminal() {
        return Mode::Off;
    }
    match std::env::var("COLORTERM") {
        Ok(v) if v == "truecolor" || v == "24bit" => Mode::TrueColor,
        _ => Mode::Ansi8,
    }
}

pub struct Painter {
    pub mode: Mode,
}

impl Painter {
    pub fn fg_bg_seq(&self, fg: &Color, bg: &Color) -> String {
        match self.mode {
            Mode::TrueColor => {
                let (fr, fgn, fb) = fg.to_rgb8();
                let (br, bgc, bb) = bg.to_rgb8();
                format!("\x1b[38;2;{};{};{};48;2;{};{};{}m", fr, fgn, fb, br, bgc, bb)
            }
            Mode::Ansi8 => {
                let fi = ansi::rgb_to_ansi256(fg);
                let bi = ansi::rgb_to_ansi256(bg);
                format!("\x1b[38;5;{};48;5;{}m", fi, bi)
            }
            Mode::Off => String::new(),
        }
    }

    pub fn fg_seq(&self, fg: &Color) -> String {
        match self.mode {
            Mode::TrueColor => {
                let (fr, fgn, fb) = fg.to_rgb8();
                format!("\x1b[38;2;{};{};{}m", fr, fgn, fb)
            }
            Mode::Ansi8 => format!("\x1b[38;5;{}m", ansi::rgb_to_ansi256(fg)),
            Mode::Off => String::new(),
        }
    }

    pub fn reset(&self) -> String {
        match self.mode {
            Mode::Off => String::new(),
            _ => "\x1b[0m".to_string(),
        }
    }
}

pub const CHECKER_A: f64 = 240.0 / 255.0;
pub const CHECKER_B: f64 = 181.0 / 255.0;

/// Render one half-block cell: fg colour on top, bg colour at bottom.
pub fn cell(p: &Painter, top: &Color, bottom: &Color) -> String {
    format!(
        "{}\u{2580}{}",
        p.fg_bg_seq(top, bottom),
        p.reset()
    )
}
RSEOF
echo ok"}

