                format!("hsl({:.0}, {:.1}%, {:.1}%)", h, s * 100.0, l * 100.0)
            }
        }
        "hsl-hue" => fmt(c.hsl().0.round(), 0),
        "hsl-saturation" => fmt(c.hsl().1, 4),
        "hsl-lightness" => fmt(c.hsl().2, 4),
