            let (h, s, v) = c.hsv();
            if c.a < 1.0 {
                format!(
                    "hsva({:.0}, {:.1}%, {:.1}%, {})",
                    h,
                    s * 100.0,
                    v * 100.0,
                    fmt_alpha(c.a)
                )
