        "hsv-hue" => fmt(c.hsv().0.round(), 0),
        "hsv-saturation" => fmt(c.hsv().1, 4),
        "hsv-value" => fmt(c.hsv().2, 4),
        "lch" => {
            let l = c.lch();
            if c.a < 1.0 {
                format!(
                    "LCh({:.0}, {:.0}, {:.0}, {})",
                    l.l,
                    l.c,
                    l.h,
                    fmt_alpha(c.a)
                )
            } else {
                format!("LCh({:.0}, {:.0}, {:.0})", l.l, l.c, l.h)
            }
        }
        "lch-lightness" => fmt(c.lch().l, 2),
        "lch-chroma" => fmt(c.lch().c, 2),
        "lch-hue" => fmt(c.lch().h, 2),
        "oklch" => {
            let (l, cc, h) = c.oklch();
            if c.a < 1.0 {
                format!(
                    "OkLCh({:.4}, {:.4}, {:.4}, {})",
                    l,
                    cc,
                    h,
                    fmt_alpha(c.a)
                )
            } else {
                format!("OkLCh({:.4}, {:.4}, {:.4})", l, cc, h)
            }
        }
        "oklch-lightness" => fmt(c.oklch().0, 4),
        "oklch-chroma" => fmt(c.oklch().1, 4),
        "oklch-hue" => fmt(c.oklch().2, 4),
        "lab" => {
            let l = c.lab();
            if c.a < 1.0 {
                format!("Lab({:.0}, {:.0}, {:.0}, {})", l.l, l.a, l.b, fmt_alpha(c.a))
            } else {
                format!("Lab({:.0}, {:.0}, {:.0})", l.l, l.a, l.b)
            }
        }
        "lab-a" => fmt(c.lab().a, 2),
        "lab-b" => fmt(c.lab().b, 2),
        "oklab" => {
            let o = c.oklab();
            if c.a < 1.0 {
                format!(
                    "OkLab({:.4}, {:.4}, {:.4}, {})",
                    o[0],
                    o[1],
                    o[2],
                    fmt_alpha(c.a)
                )
            } else {
                format!("OkLab({:.4}, {:.4}, {:.4})", o[0], o[1], o[2])
            }
        }
        "oklab-l" => fmt(c.oklab()[0], 4),
        "oklab-a" => fmt(c.oklab()[1], 4),
        "oklab-b" => fmt(c.oklab()[2], 4),
        "luminance" => fmt(c.luminance(), 3),
        "brightness" => fmt(c.brightness(), 3),
        "ansi-8bit" => {
            if c.a < 1.0 {
                format!("\\x1b[38;5;{}m", crate::ansi::rgb_to_ansi256(c))
            } else {
                format!("\\x1b[38;5;{}m", crate::ansi::rgb_to_ansi256(c))
            }
        }
        "ansi-24bit" => {
            let (r, g, b) = c.to_rgb8();
            format!("\\x1b[38;2;{};{};{}m", r, g, b)
        }
        "ansi-8bit-value" => format!("{}", crate::ansi::rgb_to_ansi256(c)),
        "ansi-8bit-escapecode" => {
            let s = crate::ansi::rgb_to_ansi256(c);
            format!("\x1b[38;5;{}m", s)
        }
        "ansi-24bit-escapecode" => {
            let (r, g, b) = c.to_rgb8();
            format!("\x1b[38;2;{};{};{}m", r, g, b)
        }
        "cmyk" => {
            let k = c.cmyk();
            if c.a < 1.0 {
                format!(
                    "cmyk({:.0}%, {:.0}%, {:.0}%, {:.0}%, {})",
