fn get_colors(p: &arg::Parsed, painter: &Painter) -> Vec<Color> {
    let mut out = vec![];
    for s in &p.colors {
        if s == "pick" {
            continue;
        }
        if s == "-" {
            continue;
        }
        if let Some(c) = Color::parse_color(s) {
            out.push(c);
        } else {
            eprintln!("[pastel error]: Could not parse color '{}'", s);
            std::process::exit(1);
        }
    }
    out
}

fn print_colors(p: &Painter, colors: &[Color]) {
    let mut first = true;
    for c in colors {
        if !first {
            println!();
        }
        first = false;
        match p.mode {
            Mode::Off => println!("{}", plain(c)),
            _ => crate::commands::print_block(p, c),
        }
    }
}

pub fn dispatch(ctx: &Ctx, p: &arg::Parsed) -> Result<(), arg::ArgError> {
    let mode = match ctx.mode {
        ColorMode::Auto => detect_mode(None),
        ColorMode::TrueColor => detect_mode(Some(Mode::TrueColor)),
        ColorMode::Ansi8 => detect_mode(Some(Mode::Ansi8)),
        ColorMode::Off => detect_mode(Some(Mode::Off)),
    };
    let painter = Painter { mode };
    match p.cmd.as_str() {
        "color" => {
            let cs = get_colors(p, &painter);
            print_colors(&painter, &cs);
        }
        "format" => {
            let cs = get_colors(p, &painter);
            for c in &cs {
                println!("{}", format_color(c, &p.format));
            }
        }
        "list" => crate::commands::list(&painter, &p.sort),
        "gray" => {
            let v = p.set_value.clamp(0.0, 1.0);
            print_colors(&painter, &[Color::from_gray(v)]);
        }
        "lighten" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs
                .iter()
                .map(|c| {
                    let (h, s, l) = c.hsl();
                    Color::from_hsl(h, s, (l + p.set_value).clamp(0.0, 1.0))
                })
                .collect();
            print_colors(&painter, &out);
        }
        "darken" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs
                .iter()
                .map(|c| {
                    let (h, s, l) = c.hsl();
                    Color::from_hsl(h, s, (l - p.set_value).clamp(0.0, 1.0))
                })
                .collect();
            print_colors(&painter, &out);
        }
        "saturate" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs
                .iter()
                .map(|c| {
                    let (h, s, l) = c.hsl();
                    Color::from_hsl(h, (s + p.set_value).clamp(0.0, 1.0), l)
                })
                .collect();
            print_colors(&painter, &out);
        }
        "desaturate" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs
                .iter()
                .map(|c| {
                    let (h, s, l) = c.hsl();
                    Color::from_hsl(h, (s - p.set_value).clamp(0.0, 1.0), l)
                })
                .collect();
            print_colors(&painter, &out);
        }
        "rotate" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs
                .iter()
                .map(|c| {
                    let (h, s, l) = c.hsl();
                    Color::from_hsl(wrap_degrees(h + p.set_value), s, l)
                })
                .collect();
            print_colors(&painter, &out);
        }
        "complement" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs
                .iter()
                .map(|c| {
                    let (h, s, l) = c.hsl();
                    Color::from_hsl(wrap_degrees(h + 180.0), s, l)
                })
                .collect();
            print_colors(&painter, &out);
        }
        "colorblind" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs
                .iter()
                .map(|c| crate::commands::colorblind(c, &p.cblind))
                .collect();
            print_colors(&painter, &out);
        }
        "to-gray" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs.iter().map(|c| crate::commands::to_gray(c)).collect();
            print_colors(&painter, &out);
        }
        "textcolor" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs
                .iter()
                .map(|c| {
                    if c.luminance() > 0.1791 {
                        Color::from_gray(0.0)
                    } else {
                        Color::from_gray(1.0)
                    }
                })
                .collect();
            print_colors(&painter, &out);
        }
        "mix" => {
            let cs = get_colors(p, &painter);
            if cs.is_empty() {
                return Ok(());
            }
            let base = cs[0];
            let out: Vec<Color> = cs
                .iter()
                .skip(1)
                .map(|c| crate::commands::mix(&base, c, p.fraction, &p.colorspace))
                .collect();
            print_colors(&painter, &out);
        }
        "gradient" => {
            let cs = get_colors(p, &painter);
            let out = crate::commands::gradient(&cs, p.number, &p.colorspace);
            print_colors(&painter, &out);
        }
        "set" => {
            let cs = get_colors(p, &painter);
            let out: Vec<Color> = cs
                .iter()
                .map(|c| crate::commands::set_prop(c, &p.set_prop, p.set_value))
                .collect();
            print_colors(&painter, &out);
        }
        "sort-by" => {
            let mut cs = get_colors(p, &painter);
            crate::commands::sort_by(&mut cs, &p.sort);
            print_colors(&painter, &cs);
        }
        "random" => {
            let n = p.number;
            let strat = p.strategy.clone().unwrap_or_else(|| "vivid".to_string());
            let out = crate::commands::random_colors(n, &strat);
            print_colors(&painter, &out);
        }
        "distinct" => {
            let n = p.count_arg.unwrap_or(10);
            let mut fixed = get_colors(p, &painter);
            let out = crate::commands::distinct(n, &mut fixed, &p.metric, p.verbose);
            print_colors(&painter, &out);
        }
        "paint" => {
            crate::commands::paint(&painter, p);
        }
        "colorcheck" => crate::commands::colorcheck(&painter),
        "pick" => {
            crate::commands::print_spectrum(&painter);
            eprintln!(
                "[pastel error]: Could not find any external color picker tool. See '{} pick --help' for more information.",
                ctx.prog
            );
            std::process::exit(1);
        }
        _ => {}
    }
    Ok(())
}
RSEOF
echo ok"}

