fn fmt_alpha(a: f64) -> String {
    let s = format!("{:.3}", a);
    let s = s.trim_end_matches('0').trim_end_matches('.').to_string();
    if s.is_empty() {
        "0".to_string()
    } else {
        s
    }
}

/// Plain (non-terminal) representation of a colour.
pub fn plain(c: &Color) -> String {
    let (h, s, l) = c.hsl();
    if c.a < 1.0 {
        format!(
            "hsla({},{:.1}%,{:.1}%,{})",
            h.round(),
            s * 100.0,
            l * 100.0,
            fmt_alpha(c.a)
        )
    } else {
        format!("hsl({},{:.1}%,{:.1}%)", h.round(), s * 100.0, l * 100.0)
    }
}

pub fn hex(c: &Color) -> String {
    let (r, g, b) = c.to_rgb8();
    if c.a < 1.0 {
        let a = (c.a * 255.0 + 0.5).floor().clamp(0.0, 255.0) as u8;
        format!("#{:02x}{:02x}{:02x}{:02x}", r, g, b, a)
    } else {
        format!("#{:02x}{:02x}{:02x}", r, g, b)
    }
}

fn fmt(v: f64, dec: usize) -> String {
