// ---------------- block display ----------------

pub fn print_block(p: &Painter, c: &Color) {
    let a = 0.24;
    let b = 0.71;
    let ca = Color::from_gray(a);
    let cb = Color::from_gray(b);
    let check = |i: usize| -> (Color, Color) {
        if i % 2 == 0 {
            (ca.clone(), cb.clone())
        } else {
            (cb.clone(), ca.clone())
        }
    };
    let fill = |i: usize| -> (Color, Color) {
