pub fn to_gray(c: &Color) -> Color {
    let l = c.luminance();
    let v = if l <= 0.0031308 {
        12.92 * l
    } else {
        1.055 * l.powf(1.0 / 2.4) - 0.055
    };
    let v = v.clamp(0.0, 1.0);
    let q = (v * 255.0 + 0.5).floor() / 255.0;
    Color::from_gray(q)
}

pub fn mix(base: &Color, other: &Color, f: f64, space: &str) -> Color {
    match space {
        "RGB" => {
            let r = other.r * (1.0 - f) + base.r * f;
            let g = other.g * (1.0 - f) + base.g * f;
            let b = other.b * (1.0 - f) + base.b * f;
            Color::new(r, g, b)
        }
        "HSL" => {
            let (h1, s1, l1) = base.hsl();
            let (h2, s2, l2) = other.hsl();
            let dh = {
                let mut d = h1 - h2;
                if d > 180.0 {
                    d -= 360.0;
                }
                if d < -180.0 {
                    d += 360.0;
                }
                d
            };
            let h = wrap_degrees(h2 + dh * f);
            Color::from_hsl(h, s2 * (1.0 - f) + s1 * f, l2 * (1.0 - f) + l1 * f)
        }
        "Lab" => {
            let a = base.lab();
            let b = other.lab();
            Color::from_lab(crate::color::Lab {
                l: b.l * (1.0 - f) + a.l * f,
                a: b.a * (1.0 - f) + a.a * f,
                b: b.b * (1.0 - f) + a.b * f,
            })
        }
        "LCh" => {
            let a = base.lch();
            let b = other.lch();
            let dh = {
                let mut d = a.h - b.h;
                if d > 180.0 {
                    d -= 360.0;
                }
                if d < -180.0 {
                    d += 360.0;
                }
                d
            };
            Color::from_lch(crate::color::LCh {
                l: b.l * (1.0 - f) + a.l * f,
                c: b.c * (1.0 - f) + a.c * f,
                h: wrap_degrees(b.h + dh * f),
            })
        }
        "OkLab" => {
            let a = base.oklab();
            let b = other.oklab();
            Color::from_oklab(
                b[0] * (1.0 - f) + a[0] * f,
                b[1] * (1.0 - f) + a[1] * f,
                b[2] * (1.0 - f) + a[2] * f,
            )
        }
        _ => *other,
    }
}

pub fn gradient(colors: &[Color], n: usize, space: &str) -> Vec<Color> {
    let mut out = vec![];
    if colors.is_empty() {
        return out;
    }
    if colors.len() == 1 {
        return vec![colors[0]];
    }
    let steps = n - 1;
    for i in 0..n {
        let t = if steps == 0 { 0.0 } else { i as f64 / steps as f64 };
        // find segment
        let seg = (t * (colors.len() - 1) as f64).floor() as usize;
        let seg = seg.min(colors.len() - 2);
        let local = t * (colors.len() - 1) as f64 - seg as f64;
        out.push(mix(&colors[seg + 1], &colors[seg], local, space));
    }
    out
}

pub fn set_prop(c: &Color, prop: &str, v: f64) -> Color {
    match prop {
        "lightness" => {
            let l = c.lch();
            Color::from_lch(crate::color::LCh { l: v, ..l })
        }
        "hue" => {
            let l = c.lch();
            Color::from_lch(crate::color::LCh { h: v, ..l })
        }
        "chroma" => {
            let l = c.lch();
            Color::from_lch(crate::color::LCh { c: v, ..l })
        }
        "lab-a" => {
            let l = c.lab();
            Color::from_lab(crate::color::Lab { a: v, ..l })
        }
        "lab-b" => {
            let l = c.lab();
            Color::from_lab(crate::color::Lab { b: v, ..l })
        }
        "oklab-l" => {
            let o = c.oklab();
            Color::from_oklab(v, o[1], o[2])
        }
        "oklab-a" => {
            let o = c.oklab();
            Color::from_oklab(o[0], v, o[2])
        }
        "oklab-b" => {
            let o = c.oklab();
            Color::from_oklab(o[0], o[1], v)
        }
        "red" => Color::new(v / 255.0, c.g, c.b),
        "green" => Color::new(c.r, v / 255.0, c.b),
        "blue" => Color::new(c.r, c.g, v / 255.0),
        "hsl-hue" => {
            let (h, s, l) = c.hsl();
            Color::from_hsl(v, s, l)
        }
        "hsl-saturation" => {
            let (h, s, l) = c.hsl();
            Color::from_hsl(h, v, l)
        }
        "hsl-lightness" => {
            let (h, s, l) = c.hsl();
            Color::from_hsl(h, s, v)
        }
        "alpha" => {
            let mut c2 = *c;
            c2.a = v.clamp(0.0, 1.0);
            c2
        }
        _ => *c,
    }
}

