pub fn to_gray(c: &Color) -> Color {
    let l = c.luminance();
    let v = if l <= 0.0031308 {
        12.92 * l
    } else {
        1.055 * l.powf(1.0 / 2.4) - 0.055
    };
    let v = v.clamp(0.0, 1.0);
    let q = (v * 255.0 + 0.5).floor() / 255.0;
