pub fn mix(base: &Color, other: &Color, f: f64, space: &str) -> Color {
    match space {
        "RGB" => {
            let r = other.r * (1.0 - f) + base.r * f;
            let g = other.g * (1.0 - f) + base.g * f;
            let b = other.b * (1.0 - f) + base.b * f;
            Color::new(r, g, b)
        }
        "HSL" => {
            let (h1, s1, l1) = base.hsl();
            let (h2, s2, l2) = other.hsl();
            let dh = {
                let mut d = h1 - h2;
                if d > 180.0 {
                    d -= 360.0;
                }
                if d < -180.0 {
                    d += 360.0;
                }
                d
            };
            let h = wrap_degrees(h2 + dh * f);
            Color::from_hsl(h, s2 * (1.0 - f) + s1 * f, l2 * (1.0 - f) + l1 * f)
        }
        "Lab" => {
            let a = base.lab();
            let b = other.lab();
            Color::from_lab(crate::color::Lab {
                l: b.l * (1.0 - f) + a.l * f,
                a: b.a * (1.0 - f) + a.a * f,
                b: b.b * (1.0 - f) + a.b * f,
            })
        }
        "LCh" => {
            let a = base.lch();
            let b = other.lch();
            let dh = {
                let mut d = a.h - b.h;
                if d > 180.0 {
                    d -= 360.0;
                }
                if d < -180.0 {
                    d += 360.0;
                }
                d
            };
            Color::from_lch(crate::color::LCh {
                l: b.l * (1.0 - f) + a.l * f,
                c: b.c * (1.0 - f) + a.c * f,
                h: wrap_degrees(b.h + dh * f),
            })
        }
        "OkLab" => {
            let a = base.oklab();
            let b = other.oklab();
            Color::from_oklab(
                b[0] * (1.0 - f) + a[0] * f,
                b[1] * (1.0 - f) + a[1] * f,
                b[2] * (1.0 - f) + a[2] * f,
            )
        }
        _ => *other,
    }
}

