            Color::from_lch(crate::color::LCh { c: v, ..l })
        }
        "lab-a" => {
            let l = c.lab();
            Color::from_lab(crate::color::Lab { a: v, ..l })
        }
        "lab-b" => {
            let l = c.lab();
            Color::from_lab(crate::color::Lab { b: v, ..l })
        }
        "oklab-l" => {
            let o = c.oklab();
            Color::from_oklab(v, o[1], o[2])
        }
        "oklab-a" => {
            let o = c.oklab();
            Color::from_oklab(o[0], v, o[2])
        }
        "oklab-b" => {
            let o = c.oklab();
            Color::from_oklab(o[0], o[1], v)
        }
        "red" => Color::new(v / 255.0, c.g, c.b),
        "green" => Color::new(c.r, v / 255.0, c.b),
        "blue" => Color::new(c.r, c.g, v / 255.0),
        "hsl-hue" => {
            let (h, s, l) = c.hsl();
            Color::from_hsl(v, s, l)
        }
        "hsl-saturation" => {
            let (h, s, l) = c.hsl();
            Color::from_hsl(h, v, l)
        }
        "hsl-lightness" => {
            let (h, s, l) = c.hsl();
            Color::from_hsl(h, s, v)
        }
        "alpha" => {
            let mut c2 = *c;
            c2.a = v.clamp(0.0, 1.0);
            c2
        }
        _ => *c,
    }
}

fn sortkey(c: &Color, order: &str) -> f64 {
    match order {
        "brightness" => c.brightness(),
        "luminance" => c.luminance(),
        "hue" => c.lch().h,
        "chroma" => c.lch().c,
        _ => 0.0,
    }
}

pub fn sort_by(cs: &mut Vec<Color>, order: &str) {
    if order == "random" {
        use rand::Seedless;
        cs.shuffle_seedless();
        return;
    }
    cs.sort_by(|x, y| {
        (sortkey(x, order) * 1000.0)
            .floor()
            .partial_cmp(&(sortkey(y, order) * 1000.0).floor())
            .unwrap()
    });
}

pub mod rand {
    pub trait Seedless {
        fn shuffle_seedless(&mut self);
    }
    impl Seedless for Vec<crate::color::Color> {
        fn shuffle_seedless(&mut self) {
            let mut state = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos() as u64)
                .unwrap_or(0);
            let n = self.len();
            for i in (1..n).rev() {
                state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
                let j = (state >> 33) as usize % (i + 1);
                self.swap(i, j);
            }
        }
    }
}

pub fn random_colors(n: usize, strat: &str) -> Vec<Color> {
    let mut state = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64 ^ std::process::id() as u64)
        .unwrap_or(1);
    let mut rnd = move || -> f64 {
        state = state
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        ((state >> 11) as f64) / ((1u64 << 53) as f64)
    };
    let mut out = vec![];
    for _ in 0..n {
        let c = match strat {
            "rgb" => Color::new(rnd(), rnd(), rnd()),
            "gray" => Color::from_gray(rnd()),
            "lch_hue" => {
                let h = rnd() * 360.0;
                Color::from_lch(crate::color::LCh { l: 60.0, c: 60.0, h })
            }
            _ => {
                let h = rnd() * 360.0;
                let s = 0.3 + rnd() * 0.5;
                let l = 0.3 + rnd() * 0.4;
                Color::from_hsl(h, s, l)
            }
        };
        out.push(c);
    }
    out
}

pub fn distinct(_n: usize, _fixed: &mut Vec<Color>, _metric: &str, _verbose: bool) -> Vec<Color> {
    // deterministic placeholder: spread hues evenly
    let mut out = vec![];
    for i in 0.._n {
        out.push(Color::from_lch(crate::color::LCh {
            l: 50.0,
            c: 100.0,
            h: (i as f64) * 360.0 / _n as f64,
        }));
    }
    out
}

pub fn paint(p: &Painter, args: &arg::Parsed) {
    let fg = match args.colors.first() {
        Some(c) => *c,
        None => return,
    };
    let mut text = args.positional[1..].join(" ");
    if text.is_empty() {
        use std::io::Read;
        let mut s = String::new();
        if std::io::stdin().read_to_string(&mut s).is_ok() {
            text = s.trim_end_matches('\n').to_string();
        }
    }
    let mut seq = p.fg_seq(&fg);
    if let Some(bg) = &args.on {
        if let Some(bgc) = Color::parse_color(bg) {
            seq = format!(
                "{};48;2;{};{};{}",
                seq.trim_start_matches("\x1b[").trim_end_matches('m'),
                bgc.to_rgb8().0,
                bgc.to_rgb8().1,
                bgc.to_rgb8().2
            );
            seq = format!("\x1b[{}m", seq);
        }
    }
    if args.bold {
        seq = seq.trim_end_matches('m').to_string() + ";1m";
    }
    if args.italic {
        seq = seq.trim_end_matches('m').to_string() + ";3m";
    }
    if args.underline {
        seq = seq.trim_end_matches('m').to_string() + ";4m";
    }
    print!("{}{}{}", seq, text, p.reset());
    if !args.no_newline {
        println!();
    }
}

pub fn colorcheck(p: &Painter) {
    let colors = [
        Color::from_rgb8(0x49, 0x27, 0x32),
        Color::from_rgb8(0x10, 0x33, 0x1e),
        Color::from_rgb8(0x1d, 0x36, 0x5a),
    ];
    println!();
    println!("8-bit mode:");
    println!("{}", " ".repeat(30));
    panel(p, &colors, true);
    println!("24-bit mode:");
    println!("{}", " ".repeat(30));
    panel(p, &colors, false);
    println!("If your terminal emulator supports 24-bit colors, you should see three square color panels in the lower row and the colors should look similar (but slightly different from) the colors in the top row panels.");
    println!("The panels in the lower row should look like squares that are filled with a uniform color (no stripes or other artifacts).");
    println!();
    println!("You can also open https://github.com/sharkdp/pastel/blob/master/doc/colorcheck.md in a browser to compare how the output should look like.");
}

fn panel(p: &Painter, colors: &[Color], bit8: bool) {
    for _row in 0..4 {
        let mut s = String::from("  ");
        for c in colors {
            for _i in 0..8 {
                let idx = if bit8 {
                    crate::ansi::rgb_to_ansi256(c)
                } else {
                    0
                };
                let _ = idx;
                s.push_str(&format!("{} {}{}", p.fg_bg_seq(c, c), " ", p.reset()));
            }
            s.push_str("  ");
        }
        println!("{}", s);
    }
}

pub fn print_spectrum(p: &Painter) {
    println!("{}", " ".repeat(52));
    for row in 0..25 {
        let mut s = String::from("  ");
        for col in 0..50 {
            if col == 0 || col == 49 {
                let w = Color::from_gray(1.0);
                if row == 0 || row == 24 {
                    s.push_str(&format!("{} {}{}", p.fg_bg_seq(&w, &w), " ", p.reset()));
                } else {
                    s.push_str(&format!("{} \u{2580}{}", p.fg_bg_seq(&w, &w), p.reset()));
                }
            } else {
                s.push_str(&format!("{} \u{2580}{}", p.fg_bg_seq(&w2(row), &w2(row)), p.reset()));
            }
        }
        println!("{}", s);
    }
    println!();
}

fn w2(_row: usize) -> Color {
    Color::from_gray(0.5)
}
