    // Simulate colour vision deficiency in linear RGB space.
    let r = crate::color::linearize(c.r);
    let g = crate::color::linearize(c.g);
    let b = crate::color::linearize(c.b);
    let m: [[f64; 3]; 3] = match ty {
        "prot" => [
            [0.11238, 0.85453, 0.03310],
            [0.11238, 0.85453, 0.03310],
            [0.00401, -0.00844, 1.00443],
        ],
        "deuter" => [
            [0.34478, 0.65552, -0.00030],
            [0.34478, 0.65552, -0.00030],
            [-0.00514, 0.00811, 0.99703],
