            [1.01499, -0.00279, -0.01220],
            [0.02946, 0.96399, 0.00655],
            [-0.01281, 0.03631, 0.97650],
        ],
    };
    let nr = m[0][0] * r + m[0][1] * g + m[0][2] * b;
    let ng = m[1][0] * r + m[1][1] * g + m[1][2] * b;
    let nb = m[2][0] * r + m[2][1] * g + m[2][2] * b;
    Color::new(
        crate::color::delinearize(crate::color::clamp01(nr)),
        crate::color::delinearize(crate::color::clamp01(ng)),
        crate::color::delinearize(crate::color::clamp01(nb)),
    )
}''')
open(p,'w').write(s)
